package de.intranda.goobi.plugins.aeon;

import java.util.List;
import java.util.Map;
import java.util.Set;

import org.apache.commons.lang3.StringUtils;

/**
 * Turns the notes AEON keeps for a request (endpoint Requests/{transactionNumber}/notes) into one text value.
 *
 * The endpoint delivers a list of notes, each with noteDate, noteText, username and noteType. Only the notes written by the researcher (User) or by
 * staff (Staff) are kept; System and ItemDetail notes are generated by AEON and say nothing about the order. Each kept note becomes one line
 * "noteDate username: noteText", oldest first, so a configured field with aeon="notes" can read all of them at once.
 */
public final class AeonNotes {

    private static final Set<String> NOTE_TYPES = Set.of("User", "Staff");

    private AeonNotes() {
        // utility class
    }

    /**
     * @param notes the deserialized notes response, may be null
     * @return one line per User or Staff note, oldest first, or an empty string if there is none
     */
    public static String format(List<Map<String, Object>> notes) {
        if (notes == null) {
            return "";
        }
        StringBuilder answer = new StringBuilder();
        for (Map<String, Object> note : notes) {
            // exclude all notes besides user and staff
            String type = asString(note.get("noteType"));
            if (NOTE_TYPES.contains(type)) {
                if (!answer.isEmpty()) {
                    answer.append("\n");
                }
                answer.append(formatNote(note));
            }
        }
        return answer.toString();
    }

    private static String formatNote(Map<String, Object> note) {
        StringBuilder line = new StringBuilder();
        String date = asString(note.get("noteDate"));
        if (StringUtils.isNotBlank(date)) {
            line.append(date).append(' ');
        }
        String username = asString(note.get("username"));
        if (StringUtils.isNotBlank(username)) {
            line.append(username);
        }
        if (line.length() > 0) {
            line.append(": ");
        }
        return line.append(asString(note.get("noteText")).trim()).toString().trim();
    }

    private static String asString(Object value) {
        return value == null ? null : String.valueOf(value);
    }
}
